package com.nthexperience.desktop;
import android.app.Activity;
import android.content.ClipData;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Ten overview, named desktops and moving built-in windows without detaching their contents. */
final class TenTaskView {
 final Activity activity;final FrameLayout host;final View wallpaper;final TenDesktops desktops;final Runnable refresh;FrameLayout overlay;LinearLayout body;final List<Bitmap> images=new ArrayList<>();int safeLeft,safeRight,safeTop;
 TenTaskView(Activity a,FrameLayout host,View wallpaper,TenDesktops desktops,Runnable refresh){activity=a;this.host=host;this.wallpaper=wallpaper;this.desktops=desktops;this.refresh=refresh;}
 void safeInsets(int l,int r,int t){safeLeft=l;safeRight=r;safeTop=t;if(overlay!=null&&(overlay.getPaddingLeft()!=l||overlay.getPaddingTop()!=t||overlay.getPaddingRight()!=r||overlay.getPaddingBottom()!=0))overlay.setPadding(l,t,r,0);}
 boolean dismiss(){if(overlay==null)return false;host.removeView(overlay);overlay=null;body=null;for(Bitmap b:images)b.recycle();images.clear();return true;}
 private int dp(int n){return Aero.dp(activity,n);}private TextView darkButton(String text,Runnable action){TextView v=TenStyle.command(activity,text,action);v.setTextColor(Color.WHITE);return v;}
 void show(List<DesktopWindow> windows,List<String> external,java.util.function.Function<String,String> label,java.util.function.Consumer<String> open){
  dismiss();desktops.sync();overlay=new FrameLayout(activity);overlay.setElevation(dp(40));overlay.setPadding(safeLeft,safeTop,safeRight,0);overlay.setContentDescription("Task View");overlay.setClickable(true);overlay.setOnClickListener(v->dismiss());overlay.setBackgroundColor(0xee171717);
  if(wallpaper!=null&&wallpaper.getWidth()>0&&wallpaper.getHeight()>0)try{float scale=Math.min(1,1400f/wallpaper.getWidth());Bitmap backdrop=Bitmap.createBitmap(Math.max(1,(int)(wallpaper.getWidth()*scale)),Math.max(1,(int)(wallpaper.getHeight()*scale)),Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(backdrop);canvas.drawColor(Color.BLACK);canvas.scale(scale,scale);wallpaper.draw(canvas);canvas.drawColor(0x88000000);images.add(backdrop);overlay.setBackground(new android.graphics.drawable.BitmapDrawable(activity.getResources(),backdrop));}catch(RuntimeException|OutOfMemoryError ignored){}
  body=Aero.column(activity);body.setPadding(dp(26),dp(16),dp(22),dp(16));overlay.addView(body,new FrameLayout.LayoutParams(-1,-1));
  LinearLayout header=new LinearLayout(activity);TextView create=darkButton("+  New desktop",()->{String previous=desktops.current(),id=desktops.create();if(id!=null){desktops.select(id);refresh.run();createdGuide(previous,id);}});create.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);create.setContentDescription("New desktop");create.setEnabled(desktops.list().size()<TenDesktops.LIMIT);header.addView(create,new LinearLayout.LayoutParams(0,dp(42),1));TextView close=darkButton("×",this::dismiss);close.setContentDescription("Close Task View");header.addView(close,new LinearLayout.LayoutParams(dp(44),dp(42)));body.addView(header);
  if(desktops.list().size()>1){HorizontalScrollView strip=new HorizontalScrollView(activity);strip.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(activity);strip.addView(row);body.addView(strip,new LinearLayout.LayoutParams(-1,dp(66)));for(TenDesktops.Desk desk:desktops.list()){LinearLayout tile=Aero.column(activity);tile.setPadding(dp(8),dp(4),dp(8),dp(4));tile.setGravity(Gravity.CENTER_VERTICAL);tile.setBackground(Aero.literal(activity,new int[]{desk.id.equals(desktops.current())?0x883b6b89:0x44222222,0x44333333},0,desk.id.equals(desktops.current())?TenStyle.accent(activity):0xff777777));tile.addView(Aero.text(activity,desk.name,13,Color.WHITE));tile.setContentDescription("Switch desktop "+desk.name);tile.setFocusable(true);tile.setOnClickListener(v->{desktops.select(desk.id);refresh.run();});ContextMenus.bind(tile,(x,y)->desktopMenu(tile,desk));tile.setOnDragListener((v,e)->{if(!(e.getLocalState() instanceof DesktopWindow))return false;if(e.getAction()==DragEvent.ACTION_DROP){if(!desktops.move((DesktopWindow)e.getLocalState(),desk.id))Toast.makeText(activity,"That tool is already open on this desktop.",Toast.LENGTH_SHORT).show();refresh.run();}return true;});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(150),dp(52));p.rightMargin=dp(10);row.addView(tile,p);}}
  ScrollView scroll=new ScrollView(activity);Flow cards=new Flow(activity);cards.setContentDescription("Task View window thumbnails");scroll.addView(cards);LinearLayout.LayoutParams sc=new LinearLayout.LayoutParams(-1,0,1);sc.topMargin=dp(20);body.addView(scroll,sc);int available=Math.max(dp(80),host.getWidth()-safeLeft-safeRight-dp(60));
  for(DesktopWindow window:windows){if(window.getParent()==null)continue;LinearLayout card=Aero.column(activity);LinearLayout bar=new LinearLayout(activity);TextView caption=Aero.text(activity,window.caption(),12,Color.WHITE);caption.setSingleLine();caption.setEllipsize(android.text.TextUtils.TruncateAt.END);bar.addView(caption,new LinearLayout.LayoutParams(0,dp(30),1));TextView x=darkButton("×",()->{window.closeWindow();refresh.run();});x.setContentDescription("Close "+window.caption());bar.addView(x,new LinearLayout.LayoutParams(dp(32),dp(30)));card.addView(bar);
   float ratio=window.getWidth()/(float)Math.max(1,window.getHeight());int targetWidth=Math.min(available,Math.max(dp(100),Math.min(dp(390),(int)(dp(190)*ratio))));int targetHeight=Math.min(dp(225),Math.max(dp(100),(int)(targetWidth/Math.max(.25f,ratio))));
   View preview;if(WindowPreviews.allowed(window)&&window.getWidth()>0&&window.getHeight()>0){try{float scale=Math.min(720f/window.getWidth(),450f/window.getHeight());Bitmap bitmap=Bitmap.createBitmap(Math.max(1,(int)(window.getWidth()*scale)),Math.max(1,(int)(window.getHeight()*scale)),Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.scale(scale,scale);window.drawPreview(canvas);images.add(bitmap);ImageView image=new ImageView(activity);image.setImageBitmap(bitmap);image.setScaleType(ImageView.ScaleType.FIT_START);preview=image;}catch(RuntimeException|OutOfMemoryError e){preview=Aero.text(activity,"Preview unavailable",12,Color.WHITE);}}else preview=Aero.text(activity,"Private preview hidden",12,Color.WHITE);
   card.addView(preview,new LinearLayout.LayoutParams(-1,targetHeight));card.setBackground(TenStyle.hover(activity,Color.TRANSPARENT));card.setContentDescription("Switch to "+window.caption());card.setFocusable(true);card.setOnClickListener(v->{dismiss();window.restore();});ContextMenus.desktopIcon(card,(x2,y2)->windowMenu(card,window),()->card.startDragAndDrop(ClipData.newPlainText("window",window.caption()),new View.DragShadowBuilder(card),window,0));cards.addView(card,new ViewGroup.LayoutParams(targetWidth,-2));
  }
  for(String id:external){String title=label.apply(id);LinearLayout card=Aero.column(activity);card.setPadding(dp(12),dp(10),dp(12),dp(12));card.setGravity(Gravity.CENTER);card.setBackground(TenStyle.hover(activity,0x77313d48));TextView caption=Aero.text(activity,title,14,Color.WHITE);Aero.bold(caption);caption.setGravity(Gravity.CENTER);caption.setMaxLines(2);card.addView(caption,new LinearLayout.LayoutParams(-1,dp(42)));ImageView icon=new ImageView(activity);try{android.content.ComponentName name=android.content.ComponentName.unflattenFromString(id);icon.setImageDrawable(activity.getPackageManager().getActivityIcon(name));}catch(Exception e){icon.setImageDrawable(activity.getDrawable(android.R.drawable.sym_def_app_icon));}icon.setScaleType(ImageView.ScaleType.FIT_CENTER);icon.setContentDescription("App icon: "+title);card.addView(icon,new LinearLayout.LayoutParams(dp(72),dp(72)));TextView hint=Aero.text(activity,"Tap to return to app",12,0xffdddddd);hint.setGravity(Gravity.CENTER);hint.setPadding(0,dp(8),0,0);card.addView(hint,new LinearLayout.LayoutParams(-1,dp(34)));card.setContentDescription("Switch to Android app "+title);card.setFocusable(true);card.setOnClickListener(v->{dismiss();open.accept(id);});cards.addView(card,new ViewGroup.LayoutParams(Math.min(available,dp(220)),-2));}
  if(cards.getChildCount()==0)cards.addView(Aero.text(activity,"This desktop starts empty. Open apps from Start or pin shortcuts here.",14,Color.WHITE),new ViewGroup.LayoutParams(available,dp(100)));
  host.addView(overlay,new FrameLayout.LayoutParams(-1,-1));overlay.bringToFront();overlay.setFocusableInTouchMode(true);overlay.requestFocus();overlay.setOnKeyListener((v,key,e)->{if(e.getAction()==KeyEvent.ACTION_UP&&(key==KeyEvent.KEYCODE_ESCAPE||key==KeyEvent.KEYCODE_BACK)){dismiss();return true;}return false;});
 }
 void createdGuide(String previous,String created){
  if(body==null||overlay==null||!desktops.current().equals(created))return;
  TenDesktops.Desk prior=desktops.desks.get(previous);String priorName=prior==null?"your previous desktop":prior.name;
  LinearLayout guide=Aero.column(activity);guide.setPadding(dp(12),dp(10),dp(12),dp(10));guide.setBackgroundColor(0xee243b4b);guide.setContentDescription("New virtual desktop guidance");
  LinearLayout heading=new LinearLayout(activity);heading.setGravity(Gravity.CENTER_VERTICAL);heading.addView(new TenStyle.Glyph(activity,"taskview",Color.WHITE),new LinearLayout.LayoutParams(dp(28),dp(28)));TextView title=Aero.text(activity,"You're on "+desktops.name(),15,Color.WHITE);Aero.bold(title);heading.addView(title,new LinearLayout.LayoutParams(0,-2,1));guide.addView(heading);
  TextView hint=Aero.text(activity,"Open Start to launch apps or add shortcuts here. To go back, tap "+priorName+" above. You can always use the Task View button on the taskbar to switch desktops.",13,Color.WHITE);hint.setTypeface(Aero.face(activity),android.graphics.Typeface.ITALIC);hint.setPadding(0,dp(8),0,dp(8));guide.addView(hint,new LinearLayout.LayoutParams(-1,-2));
  LinearLayout actions=new LinearLayout(activity);TextView back=darkButton("Return to "+priorName,()->{if(desktops.desks.containsKey(previous))desktops.select(previous);dismiss();});back.setContentDescription("Return to previous desktop");back.setMaxLines(2);actions.addView(back,new LinearLayout.LayoutParams(0,dp(48),1));TextView keep=darkButton("Use "+desktops.name(),this::dismiss);keep.setContentDescription("Continue on new desktop");keep.setMaxLines(2);actions.addView(keep,new LinearLayout.LayoutParams(0,dp(48),1));guide.addView(actions);
  body.addView(guide,Math.min(2,body.getChildCount()),new LinearLayout.LayoutParams(-1,-2));
 }
 static final class Flow extends ViewGroup {
  Flow(android.content.Context c){super(c);}
  @Override protected void onMeasure(int ws,int hs){int width=MeasureSpec.getSize(ws),x=0,y=0,row=0,gap=Aero.dp(getContext(),18);for(int i=0;i<getChildCount();i++){View child=getChildAt(i);int cw=Math.min(width,Math.max(1,child.getLayoutParams().width));child.measure(MeasureSpec.makeMeasureSpec(cw,MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(0,MeasureSpec.UNSPECIFIED));if(x>0&&x+cw>width){y+=row+gap;x=0;row=0;}x+=cw+gap;row=Math.max(row,child.getMeasuredHeight());}setMeasuredDimension(width,y+row);}
  @Override protected void onLayout(boolean changed,int l,int t,int r,int b){int width=r-l,x=0,y=0,row=0,gap=Aero.dp(getContext(),18);for(int i=0;i<getChildCount();i++){View child=getChildAt(i);int cw=child.getMeasuredWidth(),ch=child.getMeasuredHeight();if(x>0&&x+cw>width){y+=row+gap;x=0;row=0;}child.layout(x,y,x+cw,y+ch);x+=cw+gap;row=Math.max(row,ch);}}
 }
 private void desktopMenu(View anchor,TenDesktops.Desk desk){PopupMenu menu=new PopupMenu(activity,anchor);menu.getMenu().add("Rename desktop").setOnMenuItemClickListener(item->{EditText name=new EditText(activity);name.setSingleLine();name.setText(desk.name);name.setContentDescription("Desktop name");android.app.AlertDialog dialog=Aero.dialog(activity).setTitle("Rename desktop").setView(name).setPositiveButton("Save",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{if(desktops.rename(desk.id,name.getText().toString())){dialog.dismiss();refresh.run();}else name.setError("Use 1–60 characters");}));dialog.show();return true;});menu.getMenu().add("Close desktop").setEnabled(desktops.list().size()>1).setOnMenuItemClickListener(item->{if(!desktops.remove(desk.id))Toast.makeText(activity,"Move duplicated tools or make room for this desktop’s shortcuts before closing it.",Toast.LENGTH_LONG).show();refresh.run();return true;});menu.show();}
 private void windowMenu(View anchor,DesktopWindow window){PopupMenu menu=new PopupMenu(activity,anchor);SubMenu move=menu.getMenu().addSubMenu("Move to desktop");for(TenDesktops.Desk desk:desktops.list())if(!desk.id.equals(desktops.current()))move.add(desk.name).setEnabled(desktops.canMove(window,desk.id)).setOnMenuItemClickListener(item->{desktops.move(window,desk.id);refresh.run();return true;});menu.getMenu().add("Close window").setOnMenuItemClickListener(item->{window.closeWindow();refresh.run();return true;});menu.show();}
}
